package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
/** One explicit supervisor/purpose per hive. Native output counters and assignment persist together. */
public final class ApiaryJobsEvidence {
 public record Job(UUID player,String quest){public Job{Objects.requireNonNull(player);if(!ApiaryJobs.contains(quest))throw new IllegalArgumentException("Unvalidated apiary job");}}
 private final Map<ApiaryEvidence.Site,Job> jobs=new HashMap<>();
 private final Map<Job,Map<String,Integer>> produced=new HashMap<>();
 public Optional<Job> at(ApiaryEvidence.Site site){return Optional.ofNullable(jobs.get(site));}
 public void assign(ApiaryEvidence.Site site,Job job){var old=jobs.get(site);if(old!=null&&!old.player().equals(job.player()))throw new IllegalStateException("This hive already has a different registered supervisor; ask its supervisor to crouch-right-click it again to release supervision");if(!jobs.containsKey(site)&&jobs.size()>=1024||!produced.containsKey(job)&&produced.size()>=1024)throw new IllegalStateException("Apiary job evidence is full; preserve records for operator recovery");jobs.put(site,job);produced.computeIfAbsent(job,k->new HashMap<>());}
 public Map<ApiaryEvidence.Site,Job> jobsFor(UUID player,int limit){if(limit<1||limit>16)throw new IllegalArgumentException("Bounded apiary diagnostics required");var result=new LinkedHashMap<ApiaryEvidence.Site,Job>();jobs.entrySet().stream().filter(e->e.getValue().player().equals(player)).sorted(Comparator.comparingLong(e->e.getKey().pos())).limit(limit).forEach(e->result.put(e.getKey(),e.getValue()));return Map.copyOf(result);}
 public void remove(ApiaryEvidence.Site site){jobs.remove(site);}
 public Map<String,Integer> counts(Job job){return Map.copyOf(produced.getOrDefault(job,Map.of()));}
 public void record(ApiaryEvidence.Site site,Job expected,String species,int amount){if(!ApiaryEvidence.SPECIES.contains(species)||amount<1||amount>4096)throw new IllegalArgumentException("Invalid native comb yield");if(!expected.equals(jobs.get(site)))return;var counts=produced.get(expected);counts.put(species,Math.min(2304,counts.getOrDefault(species,0)+amount));}
 public CompoundTag save(){var tag=new CompoundTag();tag.putInt("schema",1);var list=new ListTag();jobs.entrySet().stream().sorted(Comparator.comparingLong(e->e.getKey().pos())).forEach(e->{var row=job(e.getValue());row.putString("dimension",e.getKey().dimension());row.putLong("pos",e.getKey().pos());list.add(row);});tag.put("jobs",list);var counts=new ListTag();produced.entrySet().stream().sorted(Comparator.comparing(e->e.getKey().toString())).forEach(e->{var row=job(e.getKey());var values=new CompoundTag();e.getValue().forEach(values::putInt);row.put("counts",values);counts.add(row);});tag.put("produced",counts);return tag;}
 private static CompoundTag job(Job job){var row=new CompoundTag();row.putUUID("player",job.player());row.putString("quest",job.quest());return row;}
 private static Job job(CompoundTag row){if(!row.hasUUID("player")||!row.contains("quest",Tag.TAG_STRING))throw new IllegalArgumentException("Invalid apiary supervisor");return new Job(row.getUUID("player"),row.getString("quest"));}
 public static ApiaryJobsEvidence load(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("schema","jobs","produced"))||!tag.contains("schema",Tag.TAG_INT)||tag.getInt("schema")!=1)throw new IllegalArgumentException("Invalid apiary jobs schema");var result=new ApiaryJobsEvidence();for(var value:rows(tag,"produced")){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("player","quest","counts"))||!row.contains("counts",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid produced comb row");var counts=row.getCompound("counts");if(!ApiaryEvidence.SPECIES.containsAll(counts.getAllKeys()))throw new IllegalArgumentException("Unvalidated comb species");var map=new HashMap<String,Integer>();for(var species:counts.getAllKeys()){if(!counts.contains(species,Tag.TAG_INT)||counts.getInt(species)<1||counts.getInt(species)>2304)throw new IllegalArgumentException("Invalid comb count");map.put(species,counts.getInt(species));}if(result.produced.put(job(row),map)!=null)throw new IllegalArgumentException("Duplicate job counts");}for(var value:rows(tag,"jobs")){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("player","quest","dimension","pos"))||!row.contains("dimension",Tag.TAG_STRING)||!row.contains("pos",Tag.TAG_LONG))throw new IllegalArgumentException("Invalid apiary assignment");var site=new ApiaryEvidence.Site(row.getString("dimension"),row.getLong("pos"));var job=job(row);if(!result.produced.containsKey(job)||result.jobs.put(site,job)!=null)throw new IllegalArgumentException("Missing or duplicate apiary assignment");}return result;}
 private static ListTag rows(CompoundTag tag,String key){if(!(tag.get(key) instanceof ListTag list)||list.size()>1024||!list.isEmpty()&&list.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid apiary job rows");return list;}
}
